css:
/* Twilight Poppies v4 — midnight navy, honey clouds, poppy accents, tuned typography */

/* ---------- Tokens ---------- */
.dark {
  --tp-dots: radial-gradient(circle at 1px 1px, rgba(240, 222, 168, 0.035) 1px, transparent 1.5px);
  --tp-heading: #f4d58d;
  --tp-strong: #fbf1d6;
  --tp-em: #e9c98a;
  --tp-inline-code-bg: rgba(232, 198, 124, 0.09);
  --tp-inline-code-border: rgba(232, 198, 124, 0.16);
  --tp-inline-code-fg: #f3b98f;
  --tp-rule: rgba(232, 198, 124, 0.14);
  --tp-quote: #b9c2cf;
  --tp-marker: #e2602f;
  --tp-link: #f08a5a;
  --tp-text-shadow: 0 1px 2px rgba(4, 8, 16, 0.55);
}
:root:not(.dark) {
  --tp-dots: radial-gradient(circle at 1px 1px, rgba(29, 74, 90, 0.06) 1px, transparent 1.5px);
  --tp-heading: #12303a;
  --tp-strong: #0e2831;
  --tp-em: #6b4a14;
  --tp-inline-code-bg: rgba(29, 74, 90, 0.07);
  --tp-inline-code-border: rgba(29, 74, 90, 0.14);
  --tp-inline-code-fg: #a43d17;
  --tp-rule: rgba(29, 74, 90, 0.16);
  --tp-quote: #46605a;
  --tp-marker: #c94d22;
  --tp-link: #b64219;
  --tp-text-shadow: none;
}

/* ---------- Font: JetBrains Mono Nerd Font everywhere ---------- */
html, body, body *:not(svg):not(svg *) {
  font-family: "JetBrainsMono Nerd Font", "JetBrainsMono NF", "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace !important;
}
html {
  font-feature-settings: "calt" 1, "liga" 1, "zero" 1;
  text-rendering: optimizeLegibility;
  -webkit-text-size-adjust: 100%;
}
/* Light-on-dark text renders crisper with grayscale AA on macOS */
.dark body { -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

/* ---------- Assistant prose ---------- */
.chat-markdown {
  line-height: 1.7 !important;
  letter-spacing: -0.012em;
  overflow-wrap: anywhere;
  hanging-punctuation: first;
  text-shadow: var(--tp-text-shadow);
}
.chat-markdown p { margin-block: 0.75em !important; }
.chat-markdown > :first-child { margin-top: 0 !important; }
.chat-markdown > :last-child { margin-bottom: 0 !important; }

.chat-markdown h1, .chat-markdown h2, .chat-markdown h3, .chat-markdown h4, .chat-markdown h5, .chat-markdown h6 {
  color: var(--tp-heading) !important;
  font-weight: 700 !important;
  line-height: 1.3 !important;
  letter-spacing: -0.025em !important;
  margin-top: 1.5em !important;
  margin-bottom: 0.5em !important;
  text-wrap: balance;
}
.chat-markdown h1 { font-size: 1.32em !important; }
.chat-markdown h2 { font-size: 1.18em !important; }
.chat-markdown h3 { font-size: 1.06em !important; }
.chat-markdown h4, .chat-markdown h5, .chat-markdown h6 { font-size: 1em !important; opacity: 0.92; }

.chat-markdown strong, .chat-markdown b { color: var(--tp-strong) !important; font-weight: 700 !important; }
.chat-markdown em, .chat-markdown i { color: var(--tp-em) !important; font-style: italic; }

.chat-markdown a {
  color: var(--tp-link) !important;
  text-decoration: underline !important;
  text-decoration-thickness: 1px !important;
  text-underline-offset: 3px !important;
  text-decoration-color: color-mix(in srgb, var(--tp-link) 40%, transparent) !important;
}
.chat-markdown a:hover { text-decoration-color: var(--tp-link) !important; }

/* Lists */
.chat-markdown ul, .chat-markdown ol { padding-left: 1.5em !important; margin-block: 0.6em !important; }
.chat-markdown li { margin-block: 0.3em !important; padding-left: 0.15em; }
.chat-markdown li > p { margin-block: 0.3em !important; }
.chat-markdown li::marker { color: var(--tp-marker); font-weight: 700; }

/* Inline code: distinct from body text */
.chat-markdown :not(pre) > code {
  background: var(--tp-inline-code-bg) !important;
  border: 1px solid var(--tp-inline-code-border) !important;
  color: var(--tp-inline-code-fg) !important;
  border-radius: 4px !important;
  padding: 0.08em 0.36em !important;
  font-size: 0.9em !important;
  letter-spacing: 0 !important;
  text-shadow: none;
  white-space: break-spaces;
}

/* Code blocks: no shadow, a bit more line air */
.chat-markdown-codeblock, .chat-markdown pre { text-shadow: none !important; }
.chat-markdown pre, .chat-markdown pre code { line-height: 1.6 !important; letter-spacing: 0 !important; font-variant-ligatures: contextual; }

/* Blockquotes */
.chat-markdown blockquote {
  border-left: 2px solid var(--tp-marker) !important;
  padding: 0.15em 0 0.15em 1em !important;
  margin-block: 0.9em !important;
  color: var(--tp-quote) !important;
  font-style: normal !important;
}

/* Rules */
.chat-markdown hr { border: 0 !important; border-top: 1px dashed var(--tp-rule) !important; margin-block: 1.6em !important; }

/* Tables */
.chat-markdown table { border-collapse: collapse !important; font-variant-numeric: tabular-nums; font-size: 0.94em; }
.chat-markdown th { color: var(--tp-heading) !important; font-weight: 700 !important; text-align: left; }
.chat-markdown th, .chat-markdown td { border-bottom: 1px solid var(--tp-rule) !important; padding: 0.45em 0.9em 0.45em 0 !important; }

/* ---------- User messages & composer ---------- */
[data-user-message-bubble] { line-height: 1.6 !important; letter-spacing: -0.008em; overflow-wrap: anywhere; }
.composer-tiptap { line-height: 1.6 !important; letter-spacing: -0.008em; caret-color: var(--tp-marker); }
.composer-tiptap p.is-editor-empty:first-child::before { opacity: 0.85; }

/* ---------- Sidebar & chrome ---------- */
[data-thread-item] { letter-spacing: -0.015em; }
[data-chat-header] { letter-spacing: -0.015em; }
[data-slot="tooltip-popup"], [data-slot="menu-popup"], [data-slot="popover-popup"] { letter-spacing: -0.01em; line-height: 1.45; }

/* Numbers line up everywhere */
body { font-variant-numeric: tabular-nums; }

/* ---------- Background & texture ---------- */
.dark [data-workspace-area="conversation"] {
  background:
    var(--tp-dots) 0 0 / 6px 6px,
    linear-gradient(to bottom, rgba(10, 17, 32, 0.97) 0%, rgba(10, 17, 32, 0.9) 40%, rgba(10, 17, 32, 0.78) 70%, rgba(10, 17, 32, 0.62) 100%),
    var(--theme-background-image) center bottom / cover no-repeat,
    #0a1120 !important;
}
:root:not(.dark) [data-workspace-area="conversation"] {
  background:
    var(--tp-dots) 0 0 / 6px 6px,
    linear-gradient(to bottom, rgba(243, 231, 198, 0.96) 0%, rgba(243, 231, 198, 0.9) 40%, rgba(243, 231, 198, 0.8) 70%, rgba(243, 231, 198, 0.68) 100%),
    var(--theme-background-image) center bottom / cover no-repeat,
    #f3e7c6 !important;
}
[data-slot="sidebar-inner"] {
  background-image: var(--tp-dots) !important;
  background-size: 6px 6px !important;
}

/* Chat header */
.dark [data-chat-header] { background: rgba(7, 13, 25, 0.85) !important; backdrop-filter: blur(8px); }
:root:not(.dark) [data-chat-header] { background: rgba(236, 220, 179, 0.85) !important; backdrop-filter: blur(8px); }

/* Composer card */
.dark [data-slot="composer-host"] {
  background: rgba(15, 24, 41, 0.96) !important;
  border: 1px solid rgba(232, 198, 124, 0.28) !important;
  box-shadow: 0 12px 32px -12px rgba(0, 0, 0, 0.75) !important;
}
:root:not(.dark) [data-slot="composer-host"] {
  background: rgba(251, 244, 224, 0.96) !important;
  border: 1px solid rgba(201, 77, 34, 0.25) !important;
  box-shadow: 0 10px 30px -14px rgba(29, 74, 90, 0.35) !important;
}
[data-slot="composer-host"]:focus-within { border-color: #e2602f !important; }

/* User bubble */
.dark [data-user-message-bubble] { border: 1px solid rgba(232, 198, 124, 0.15) !important; }
:root:not(.dark) [data-user-message-bubble] { border: 1px solid rgba(93, 107, 44, 0.2) !important; }

/* Code blocks */
.dark .chat-markdown-codeblock { border: 1px solid rgba(232, 198, 124, 0.12) !important; }
:root:not(.dark) .chat-markdown-codeblock { border: 1px solid rgba(29, 74, 90, 0.15) !important; }

/* Selected thread: poppy marker */
[data-thread-item][data-active="true"], [data-thread-item][aria-current="page"] { box-shadow: inset 2px 0 0 #e2602f !important; }

/* Popups */
.dark [data-slot="dialog-popup"], .dark [data-slot="popover-popup"], .dark [data-slot="menu-popup"] { border-color: rgba(232, 198, 124, 0.18) !important; }

/* Scrollbars: honey thumbs */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: rgba(201, 168, 101, 0.3); border-radius: 8px; border: 2px solid transparent; background-clip: padding-box; }
::-webkit-scrollbar-thumb:hover { background: rgba(226, 96, 47, 0.6); background-clip: padding-box; }
[data-slot="scroll-area-thumb"] { background: rgba(201, 168, 101, 0.35) !important; }

/* Selection */
.dark ::selection { background: rgba(226, 96, 47, 0.38); color: #fff4e0; text-shadow: none; }
:root:not(.dark) ::selection { background: rgba(232, 198, 124, 0.6); }
